1	import { useState } from 'react';
2	import type { Meta, StoryObj } from '@storybook/react-vite';
3	import { Checkbox } from './Checkbox';
4	import {
5	  CheckboxChecked,
6	  CheckboxVariant,
7	  type CheckboxChecked as CheckboxCheckedValue,
8	} from './constants';
9	import { LabelText } from '../Text';
10	
11	const meta = {
12	  title: 'Inputs/Checkbox',
13	  component: Checkbox,
14	  parameters: { layout: 'centered' },
15	  tags: ['autodocs'],
16	  argTypes: {
17	    variant: {
18	      control: 'select',
19	      options: Object.values(CheckboxVariant),
20	    },
21	  },
22	} satisfies Meta<typeof Checkbox>;
23	
24	export default meta;
25	type Story = StoryObj<typeof meta>;
26	
27	export const Unchecked: Story = {
28	  args: {
29	    variant: CheckboxVariant.prominent,
30	  },
31	};
32	
33	export const Checked: Story = {
34	  args: {
35	    checked: CheckboxChecked.checked,
36	    variant: CheckboxVariant.prominent,
37	  },
38	};
39	
40	export const Indeterminate: Story = {
41	  args: {
42	    checked: CheckboxChecked.indeterminate,
43	    variant: CheckboxVariant.prominent,
44	  },
45	};
46	
47	export const Primary: Story = {
48	  args: {
49	    checked: CheckboxChecked.checked,
50	    variant: CheckboxVariant.primary,
51	  },
52	};
53	
54	export const Disabled: Story = {
55	  args: {
56	    disabled: true,
57	  },
58	};
59	
60	export const DisabledChecked: Story = {
61	  args: {
62	    checked: CheckboxChecked.checked,
63	    disabled: true,
64	    variant: CheckboxVariant.primary,
65	  },
66	};
67	
68	export const WithLabel: Story = {
69	  render: () => (
70	    <label className="flex items-center gap-sm">
71	      <Checkbox defaultChecked />
72	      <LabelText>Accept terms</LabelText>
73	    </label>
74	  ),
75	};
76	
77	export const Controlled: Story = {
78	  render: () => {
79	    const [checked, setChecked] = useState<CheckboxCheckedValue>(
80	      CheckboxChecked.unchecked,
81	    );
82	
83	    return (
84	      <label className="flex items-center gap-sm">
85	        <Checkbox checked={checked} onCheckedChange={setChecked} />
86	        <LabelText>
87	          {checked === CheckboxChecked.checked ? 'Enabled' : 'Disabled'}
88	        </LabelText>
89	      </label>
90	    );
91	  },
92	};
93	
94	export const AllStates: Story = {
95	  render: () => (
96	    <div className="flex flex-col gap-lg p-lg">
97	      {Object.values(CheckboxVariant).map((variant) => (
98	        <div key={variant} className="flex items-center gap-lg">
99	          <LabelText className="w-14 capitalize text-text-secondary">
100	            {variant}
101	          </LabelText>
102	          <Checkbox variant={variant} />
103	          <Checkbox variant={variant} checked={CheckboxChecked.checked} />
104	          <Checkbox variant={variant} checked={CheckboxChecked.indeterminate} />
105	          <Checkbox variant={variant} disabled />
106	          <Checkbox
107	            variant={variant}
108	            checked={CheckboxChecked.checked}
109	            disabled
110	          />
111	        </div>
112	      ))}
113	    </div>
114	  ),
115	};
