1	/*
2	 * Layout and state helpers bound to design tokens (--ui-*).
3	 *
4	 * Prefer these plain CSS utilities over Tailwind arbitrary `*-(--var)` or
5	 * `[var(--var)]` in component source: the JSX references stable class names
6	 * while declarations stay vanilla CSS compatible with shipped styles.css —
7	 * Tailwind-only syntax is avoided for token wiring so the sheet remains
8	 * approachable for consumers who bundle CSS without Tailwind.
9	 */
10	
11	/* LinearProgressIndicator — types --progress-pct as a <number>. The
12	 * fill/remainder motion is a width/left transition (.ds-progress-* below), not
13	 * a transition of this property. Outside @layer: an at-rule, kept in this file
14	 * with the rest of its system. */
15	@property --progress-pct {
16	  syntax: "<number>";
17	  inherits: true;
18	  initial-value: 0;
19	}
20	
21	/* ProgressIndicator (flat) — the ONE animated value of the ring: progress
22	 * 0–1, set inline on the <svg>. Registered as a <number> so it interpolates;
23	 * .ds-progress-ring transitions it and both arcs derive every dash value from
24	 * it (see .ds-progress-ring-* below). */
25	@property --ds-pi-progress {
26	  syntax: "<number>";
27	  inherits: true;
28	  initial-value: 0;
29	}
30	
31	@layer utilities {
32	  /*
33	   * Motion helpers — the only way a component's className reaches the motion
34	   * scale (--ui-motion-* in tokens.css). Components never write duration-N,
35	   * ease-* or inline timing; reduced motion needs nothing here, because the
36	   * global block in tokens.css collapses the scale itself.
37	   */
38	
39	  /* Hover / press / focus feedback. Lists every paint a state change touches
40	   * — colours, background, border, outline (the focus rings are outlines),
41	   * shadow, opacity, filter — plus the transform family, so a press scale or
42	   * nudge still eases like it did under `transition-all`. Layout properties
43	   * are deliberately left out: none of these controls animates its size.
44	   *
45	   * Wrapped in :where() so it has zero specificity: a consumer's own
46	   * `transition-*` / `duration-*` class on the same element still wins, as it
47	   * did when the component carried those utilities itself. */
48	  :where(.ds-motion-state) {
49	    transition-property:
50	      color, background-color, border-color, outline-color,
51	      text-decoration-color, fill, stroke, opacity, box-shadow, filter,
52	      transform, translate, scale, rotate;
53	    transition-duration: var(--ui-motion-duration-fast);
54	    transition-timing-function: var(--ui-motion-ease-standard);
55	  }
56	
57	  /* Overlay enter/exit for the tailwindcss-animate keyframes (animate-in /
58	   * animate-out + fade-* / zoom-* / slide-*), keyed off Radix `data-state`.
59	   * These set only the duration and curve; the component keeps the keyframe
60	   * utilities that pick WHAT moves. Entering uses the `enter` curve, leaving
61	   * the `exit` curve. The selectors carry the state on purpose: they must
62	   * outrank the plugin's `data-[state=…]:animate-in`, which hard-codes its
63	   * own default duration at the same (0,2,0) specificity and loses only on
64	   * source order to this later layer block.
65	   *
66	   *   ds-motion-overlay        — small overlays: menu, tooltip, popover,
67	   *                              toast. fast in, fast out. Tooltip's
68	   *                              delayed-open / instant-open count as open.
69	   *   ds-motion-overlay-dialog — modal panel + backdrop. base in, fast out.
70	   *   ds-motion-overlay-sheet  — sheet panel + backdrop. slow in, base out. */
71	  .ds-motion-overlay:is(
72	      [data-state="open"],
73	      [data-state="delayed-open"],
74	      [data-state="instant-open"]
75	    ) {
76	    animation-duration: var(--ui-motion-duration-fast);
77	    animation-timing-function: var(--ui-motion-ease-enter);
78	  }
79	  .ds-motion-overlay[data-state="closed"] {
80	    animation-duration: var(--ui-motion-duration-fast);
81	    animation-timing-function: var(--ui-motion-ease-exit);
82	  }
83	  /* Toast swipe released short of the dismiss threshold: the toast springs
84	   * back to rest. Radix sets data-swipe="cancel" and clears the move offset;
85	   * this is the transition that carries it home. */
86	  .ds-motion-overlay[data-swipe="cancel"] {
87	    transition-property: transform, translate;
88	    transition-duration: var(--ui-motion-duration-fast);
89	    transition-timing-function: var(--ui-motion-ease-standard);
90	  }
91	  .ds-motion-overlay-dialog[data-state="open"] {
92	    animation-duration: var(--ui-motion-duration-base);
93	    animation-timing-function: var(--ui-motion-ease-enter);
94	  }
95	  .ds-motion-overlay-dialog[data-state="closed"] {
96	    animation-duration: var(--ui-motion-duration-fast);
97	    animation-timing-function: var(--ui-motion-ease-exit);
98	  }
99	  .ds-motion-overlay-sheet[data-state="open"] {
100	    animation-duration: var(--ui-motion-duration-slow);
101	    animation-timing-function: var(--ui-motion-ease-enter);
102	  }
103	  .ds-motion-overlay-sheet[data-state="closed"] {
104	    animation-duration: var(--ui-motion-duration-base);
105	    animation-timing-function: var(--ui-motion-ease-exit);
106	  }
107	
108	  /* Disabled / inactive (native :disabled + aria-disabled="true") */
109	  .ds-disabled-state:is(:disabled, [aria-disabled="true"]) {
110	    cursor: not-allowed;
111	    opacity: var(--ui-opacity-disabled);
112	  }
113	
114	  /*
115	   * Radix primitives set data-disabled on menu items etc.
116	   * Does not imply :disabled; keep separate from ds-disabled-state.
117	   */
118	  .ds-radix-data-disabled[data-disabled] {
119	    cursor: not-allowed;
120	    opacity: var(--ui-opacity-disabled);
121	  }
122	
123	  /* Offset variant of ds-focus-visible-ring for organic (non-rectangular)
124	   * shapes, where a flush ring would cut through the shape. */
125	  .ds-shape-button-focus-visible:focus-visible:not(:disabled):not([data-disabled]):not(
126	      [aria-disabled="true"]
127	    ) {
128	    outline: 2px solid var(--ui-color-focus-ring-prominent);
129	    outline-offset: 2px;
130	  }
131	
132	  .ds-shape-button-shadow {
133	    filter: drop-shadow(var(--ui-shadow-button-secondary));
134	    transition-property: color, filter;
135	    transition-duration: var(--ui-motion-duration-fast);
136	    transition-timing-function: var(--ui-motion-ease-standard);
137	  }
138	
139	  .group:not(:disabled):not([aria-disabled="true"]):hover .ds-shape-button-shadow {
140	    filter: drop-shadow(var(--ui-shadow-button-hover));
141	  }
142	
143	  .group:not(:disabled):not([aria-disabled="true"]):active .ds-shape-button-shadow {
144	    filter: drop-shadow(var(--ui-shadow-button-active));
145	  }
146	
147	  .group:is(:disabled, [aria-disabled="true"]) .ds-shape-button-shadow {
148	    filter: none;
149	  }
150	
151	  /* Compact controls opt into the small ring width; every ds-focus-* helper reads it. */
152	  .ds-focus-ring-sm {
153	    --ds-focus-ring-width: var(--ui-focus-ring-width-sm);
154	  }
155	
156	  .ds-focus-visible-ring {
157	    outline: var(--ds-focus-ring-width, var(--ui-focus-ring-width)) solid transparent;
158	    outline-offset: 0;
159	  }
160	
161	  .ds-focus-visible-ring:focus-visible:not(:disabled):not([data-disabled]):not(
162	      [aria-disabled="true"]
163	    ) {
164	    outline-color: var(--ui-color-focus-ring-prominent);
165	  }
166	
167	  .ds-focus-within-ring {
168	    outline: var(--ds-focus-ring-width, var(--ui-focus-ring-width)) solid transparent;
169	    outline-offset: 0;
170	  }
171	
172	  .ds-focus-within-ring:focus-within {
173	    outline-color: var(--ui-color-focus-ring-prominent);
174	  }
175	
176	  /* Danger colour for a ds-focus-within-ring wrapper (Input with an icon or
177	   * the number variant, where the chrome is a wrapper, not the <input>). */
178	  .ds-focus-within-ring-danger:focus-within {
179	    outline-color: var(--ui-color-focus-ring-danger);
180	  }
181	
182	  .ds-focus-ring-on-focus {
183	    outline: var(--ds-focus-ring-width, var(--ui-focus-ring-width)) solid transparent;
184	    outline-offset: 0;
185	  }
186	
187	  .ds-focus-ring-on-focus:focus {
188	    outline-color: var(--ui-color-focus-ring-prominent);
189	  }
190	
191	  .ds-focus-ring-danger-on-focus:focus {
192	    outline-color: var(--ui-color-focus-ring-danger);
193	  }
194	
195	  /* Open-state ring for popover/menu triggers. The state lives in the SELECTOR,
196	   * not in a Tailwind variant: `data-[state=open]:<any ds-* class>` composes a
197	   * variant with a package class, which emits no rule at all. */
198	  .ds-focus-ring-on-open {
199	    outline: var(--ds-focus-ring-width, var(--ui-focus-ring-width)) solid transparent;
200	    outline-offset: 0;
201	  }
202	
203	  .ds-focus-ring-on-open[data-state="open"] {
204	    outline-color: var(--ui-color-focus-ring-prominent);
205	  }
206	
207	  /* Active slider track — the handle color at --ds-slider-track-opacity (the
208	   * variant's --ui-slider-track-*-active-opacity; Figma applies alpha on top).
209	   * The Slider root sets --ds-slider-color (its `color` prop, else the
210	   * variant's hue) and --ds-slider-track-opacity (from `variant`). */
211	  .ds-slider-fill {
212	    background-color: color-mix(
213	      in srgb,
214	      var(--ds-slider-color, var(--ui-color-primary))
215	        var(--ds-slider-track-opacity, var(--ui-slider-track-primary-active-opacity)),
216	      transparent
217	    );
218	  }
219	
220	  /* Slider geometry. The Slider root sets --ds-slider-pct, --ds-slider-pad and
221	   * --ds-slider-color inline. The thumb-aligned term
222	   * (pct / 100 × (100% − handle) …) is the same formula as thumbAlignedLeft()
223	   * in Slider.tsx — change them together, or the fills drift off the thumb.
224	   * Helpers, not utilities: none of these elements takes the consumer's
225	   * className (that goes to Slider's outer box), so nothing needs to merge. */
226	  .ds-slider-root {
227	    height: var(--ui-height-slider-handle);
228	  }
229	  .ds-slider-active-part {
230	    left: calc(-1 * var(--ds-slider-pad));
231	    width: max(0px, calc(var(--ds-slider-pct) / 100 * (100% - var(--ui-width-slider-handle)) - var(--ui-slider-track-gap) + var(--ds-slider-pad)));
232	  }
233	  .ds-slider-inactive-part {
234	    right: calc(-1 * var(--ds-slider-pad));
235	    left: min(100%, calc(var(--ds-slider-pct) / 100 * (100% - var(--ui-width-slider-handle)) + var(--ui-width-slider-handle) + var(--ui-slider-track-gap)));
236	  }
237	  .ds-slider-thumb {
238	    width: var(--ui-width-slider-handle);
239	    height: var(--ui-height-slider-handle);
240	    background-color: var(--ds-slider-color);
241	  }
242	
243	  /* Linear progress — width/left transition whenever --progress-pct changes
244	   * their computed value. The root sets --progress-pct and --ds-progress-color
245	   * inline. The fill never narrows below the bar's height (a round nub at 0%);
246	   * fill and remainder sit --ui-spacing-xxs apart, half on each side of the
247	   * value. Helpers, not utilities: only the root takes the consumer's
248	   * className (its height is the mergeable `h-linear-progress`). */
249	  .ds-progress-fill {
250	    width: max(var(--ui-height-linear-progress), calc(var(--progress-pct) * 1% - var(--ui-spacing-xxs) / 2));
251	    background-color: var(--ds-progress-color);
252	    transition: width var(--ui-motion-duration-slow)
253	      var(--ui-motion-ease-standard);
254	  }
255	  .ds-progress-remainder {
256	    left: max(var(--ui-height-linear-progress), min(100%, calc(var(--progress-pct) * 1% + var(--ui-spacing-xxs) / 2)));
257	    transition: left var(--ui-motion-duration-slow)
258	      var(--ui-motion-ease-standard);
259	  }
260	  /* Circular progress (ProgressIndicator, flat variant). The <svg> sets
261	   * --ds-pi-progress (0–1), --ds-pi-c (circumference) and --ds-pi-gap (the M3
262	   * gap, round-cap allowance included) inline, all in user units. ONLY
263	   * --ds-pi-progress transitions; every dash value of both arcs is a calc() of
264	   * it, so each frame is one consistent drawing. Do not transition the dash
265	   * properties themselves: four independent transitions restart from their
266	   * own mid-flight values when interrupted, and the track's length and offset
267	   * disagree — it slides backwards or its length hits 0 and it vanishes.
268	   *
269	   * Track (complement of the indicator, a gap clear of each end):
270	   *   gap   = --ds-pi-gap × --ds-pi-gap-on, where gap-on is a discrete 0|1
271	   *           set inline from the TARGET progress (> 0). It is a plain custom
272	   *           property (not registered), so it never transitions: the end gaps
273	   *           appear / vanish at once, as in the static M3 form, while only
274	   *           the arc scalar animates.
275	   *   start = C·p + gap   → dashoffset −start
276	   *   len   = C·(1 − p) − 2·gap → dasharray "len C"
277	   * A zero-length round-capped dash still paints a dot, so each arc's
278	   * stroke-opacity drops to 0 when its length is ≤ 0 (the elements stay
279	   * mounted; nothing remounts mid-animation). */
280	  .ds-progress-ring {
281	    transition: --ds-pi-progress var(--ui-motion-duration-slow)
282	      var(--ui-motion-ease-standard);
283	  }
284	  .ds-progress-ring-indicator {
285	    stroke-dasharray: calc(var(--ds-pi-c) * 1px);
286	    stroke-dashoffset: calc(var(--ds-pi-c) * (1 - var(--ds-pi-progress)) * 1px);
287	    stroke-opacity: clamp(0, var(--ds-pi-c) * var(--ds-pi-progress) * 1000000, 1);
288	  }
289	  .ds-progress-ring-track {
290	    --ds-pi-gap-now: calc(var(--ds-pi-gap) * var(--ds-pi-gap-on));
291	    --ds-pi-track-len: calc(var(--ds-pi-c) * (1 - var(--ds-pi-progress)) - 2 * var(--ds-pi-gap-now));
292	    stroke-dasharray: max(0px, var(--ds-pi-track-len) * 1px) calc(var(--ds-pi-c) * 1px);
293	    stroke-dashoffset: calc((var(--ds-pi-c) * var(--ds-pi-progress) + var(--ds-pi-gap-now)) * -1px);
294	    stroke-opacity: clamp(0, var(--ds-pi-track-len) * 1000000, 1);
295	  }
296	  /* Stepped slider dots. The active/inactive split is a plain attribute
297	   * selector rather than a Tailwind `data-[active]:` variant — variants only
298	   * compose with generated utilities, so pairing one with a class defined here
299	   * silently produced no rule and every dot stayed the inactive tone.
300	   *
301	   * The helper owns the dot's geometry too, so the highlighted step can grow
302	   * from it. ONLY `height` transitions: the colour flip stays discrete on
303	   * purpose (see the step-dot comment in Slider.tsx). The dot is centred with
304	   * a -50% translate of its own height, so it grows from its centre. */
305	  .ds-slider-dot {
306	    width: var(--ui-size-slider-step);
307	    height: var(--ui-size-slider-step);
308	    background-color: var(--ui-color-slider-step-inactive);
309	    transition-property: height;
310	    transition-duration: var(--ui-motion-duration-base);
311	    transition-timing-function: var(--ui-motion-ease-standard);
312	  }
313	
314	  /* The step a slider's `highlightedStep` picks: same width and paint, drawn
315	   * tall. Plain attribute selector for the same reason as [data-active]. */
316	  /* Only the highlighted dot fades its colour. The other dots switch paint
317	   * instantly on purpose: a fast drag sweeps many of them at once, and staggered
318	   * fades read as lag. A single dot cannot lag, so it may ease. */
319	  .ds-slider-dot[data-highlighted] {
320	    height: var(--ui-height-slider-step-tall);
321	    transition-property: height, background-color;
322	  }
323	
324	  /* During a drag the tall step marks the value the drag started from, so it
325	   * takes the solid slider colour on BOTH sides of the thumb until release.
326	   * On the filled side it still reads: the fill is the same colour at
327	   * --ds-slider-track-opacity (50-70%), the dot is opaque. Outranks the
328	   * [data-active] paint by specificity, so no JS or grouping change is needed. */
329	  [data-dragging] .ds-slider-dot[data-highlighted] {
330	    background-color: var(--ds-slider-color, var(--ui-color-primary));
331	  }
332	
333	  /* The active dot is a flat token, not a mix of --ds-slider-color: Figma
334	   * composes it from the CONTENT paint, because it is the mark read ON the
335	   * filled track rather than part of the fill. A plain attribute selector, NOT
336	   * a `data-[active]:` Tailwind variant — a variant only composes with
337	   * generated utilities, and pairing one with a class defined here emits no
