import {
  forwardRef,
  type ComponentPropsWithoutRef,
  type ComponentRef,
  type ReactNode,
} from "react";
import * as CheckboxPrimitive from "@radix-ui/react-checkbox";
import { cn } from "../../utils/cn";
import { Checkbox, type CheckboxProps } from "../Checkbox/Checkbox";
import { BodyText, LabelText } from "../Text";
import type { CheckboxVariant } from "../Checkbox/constants";

export interface CheckboxFieldProps
  extends Omit<ComponentPropsWithoutRef<typeof CheckboxPrimitive.Root>, "children"> {
  /** Text rendered beside the checkbox. */
  label: ReactNode;
  /** Smaller line of text below the label. */
  hint?: ReactNode;
  /** Checked / indeterminate fill passed to the inner Checkbox. Defaults to `prominent`. */
  variant?: CheckboxVariant;
  /** Extra classes on the outer `<label>` wrapper. */
  className?: string;
}

const CheckboxField = forwardRef<
  ComponentRef<typeof CheckboxPrimitive.Root>,
  CheckboxFieldProps
>(({ label, hint, variant, className, disabled, ...checkboxProps }, ref) => (
  <label
    className={cn(
      "flex cursor-pointer items-start gap-sm",
      disabled && "cursor-not-allowed",
      className,
    )}
  >
    <Checkbox
      ref={ref}
      variant={variant}
      disabled={disabled}
      className="mt-xxs shrink-0"
      {...checkboxProps}
    />
    <span className="flex min-w-0 flex-col gap-xxs">
      <LabelText
        className={cn(
          disabled && "text-text-disabled",
        )}
      >
        {label}
      </LabelText>
      {hint != null && (
        <BodyText
          className={cn(
            "text-text-secondary",
            disabled && "text-text-disabled",
          )}
        >
          {hint}
        </BodyText>
      )}
    </span>
  </label>
));
CheckboxField.displayName = "CheckboxField";

export { CheckboxField };

